<html lang="en">
<head>
<meta charset="utf-8">
<title>Neon Neural Growth</title>
<style>
  html, body { margin: 0; height: 100%; background: #05070f; overflow: hidden; }
  body { display: flex; align-items: center; justify-content: center; }
  canvas { width: 800px; height: 800px; box-shadow: 0 0 40px rgba(0, 229, 255, 0.15); border: 1px solid rgba(255, 212, 0, 0.25); }
  .dg.main { --accent: #ffd400; }
  .dg .cr.function .property-name { color: #ffd400; }
  .dg li.title { border-left: 3px solid #ffd400 !important; }
</style>
<script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
</head>
<body>
<canvas id="c" width="800" height="800"></canvas>
<script>
// ================= SETUP =================
const W = 800, H = 800, MAX_BRANCHES = 650, STEP = 4;
const cv = document.getElementById('c'), ctx = cv.getContext('2d');
const GLOW = '#101a3a', UI = '#ffd400', GRID = 'rgba(0, 229, 255, 0.08)';
const cfg = {
  neuronCount: 4, growSpeed: 2, maxDepth: 5, splitChance: 0.5, curvature: 0.35, maxLength: 160,
  synDist: 14, synGlow: 22,
  pulseSpeed: 260, pulseFreq: 2.5, pulseBright: 18,
  bgColor: '#05070f', branchColor: '#00e5ff', accentColor: '#d6ff00', synColor: '#ff2bd6', pulseColor: '#fff36a',
  regenerate: () => generate(),
  clear: () => { branches = []; synapses = []; pulses = []; somas = []; growing = false; },
  pause: () => { paused = !paused; pauseCtrl.name(paused ? 'Resume animation' : 'Pause animation'); }
};
let branches = [], synapses = [], pulses = [], somas = [], synKeys = new Set();
let growing = false, paused = false, pulseTimer = 0, growAcc = 0, frame = 0, last = performance.now(), pauseCtrl;
const rnd = (a, b) => a + Math.random() * (b - a);

// ================= GUI SETUP =================
function setupGUI() {
  const gui = new dat.GUI({ width: 300 });
  const g = gui.addFolder('Growth');
  g.add(cfg, 'neuronCount', 3, 6, 1).name('Neuron count');
  g.add(cfg, 'growSpeed', 0.5, 8, 0.1).name('Growth speed');
  g.add(cfg, 'maxDepth', 1, 8, 1).name('Max depth');
  g.add(cfg, 'splitChance', 0, 1, 0.01).name('Split chance');
  g.add(cfg, 'curvature', 0, 1, 0.01).name('Curvature');
  g.add(cfg, 'maxLength', 40, 300, 1).name('Max branch length');
  const s = gui.addFolder('Synapses');
  s.add(cfg, 'synDist', 4, 40, 1).name('Distance threshold');
  s.add(cfg, 'synGlow', 0, 50, 1).name('Glow strength');
  const p = gui.addFolder('Pulses');
  p.add(cfg, 'pulseSpeed', 50, 800, 5).name('Speed');
  p.add(cfg, 'pulseFreq', 0.2, 10, 0.1).name('Frequency');
  p.add(cfg, 'pulseBright', 0, 40, 1).name('Brightness');
  const v = gui.addFolder('Visuals');
  v.addColor(cfg, 'bgColor').name('Background');
  v.addColor(cfg, 'branchColor').name('Branch');
  v.addColor(cfg, 'accentColor').name('Accent branch');
  v.addColor(cfg, 'synColor').name('Synapse');
  v.addColor(cfg, 'pulseColor').name('Pulse');
  gui.add(cfg, 'regenerate').name('Regenerate network');
  gui.add(cfg, 'clear').name('Clear canvas');
  pauseCtrl = gui.add(cfg, 'pause').name('Pause animation');
  [g, s, p, v].forEach(f => f.open());
}

// ================= NEURON GROWTH =================
function newBranch(x, y, angle, depth, neuron, parent, parentIdx, accent) {
  if (branches.length >= MAX_BRANCHES) return null;
  const b = {
    id: branches.length, pts: [{ x, y }], angle, depth, neuron, parent, parentIdx, accent,
    len: 0, maxLen: cfg.maxLength * rnd(0.6, 1.1) * (1 - depth * 0.1) * (accent ? 0.5 : 1),
    w: Math.max(0.6, (2.2 - depth * 0.3) * rnd(0.7, 1.25)), active: true, tipSyn: false
  };
  branches.push(b);
  return b;
}
function generate() {
  cfg.clear();
  synKeys.clear();
  const n = Math.round(cfg.neuronCount);
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2 + rnd(-0.4, 0.4), r = rnd(40, 170);
    const x = W / 2 + Math.cos(a) * r, y = H / 2 + Math.sin(a) * r;
    somas.push({ x, y, phase: rnd(0, 6.28) });
    const k = Math.floor(rnd(3, 6)), off = rnd(0, 6.28);
    for (let j = 0; j < k; j++) newBranch(x, y, off + (j / k) * Math.PI * 2 + rnd(-0.3, 0.3), 0, i, -1, 0, false);
  }
  growing = true;
}
function growStep() {
  let any = false;
  const list = branches.slice(); // snapshot so new children start next step
  for (const b of list) {
    if (!b.active) continue;
    any = true;
    const tip = b.pts[b.pts.length - 1];
    b.angle += rnd(-1, 1) * cfg.curvature;
    const nx = tip.x + Math.cos(b.angle) * STEP, ny = tip.y + Math.sin(b.angle) * STEP;
    b.pts.push({ x: nx, y: ny });
    b.len += STEP;
    const idx = b.pts.length - 1;
    if (nx < 15 || ny < 15 || nx > W - 15 || ny > H - 15 || b.len > b.maxLen) { b.active = false; continue; }
    // fork into two children
    if (b.depth < cfg.maxDepth && b.len > 30 && Math.random() < cfg.splitChance * 0.04) {
      newBranch(nx, ny, b.angle + rnd(0.3, 0.8), b.depth + 1, b.neuron, b.id, idx, false);
      newBranch(nx, ny, b.angle - rnd(0.3, 0.8), b.depth + 1, b.neuron, b.id, idx, false);
      b.active = false;
    } else if (b.depth < cfg.maxDepth && b.len > 20 && Math.random() < cfg.splitChance * 0.02) {
      // smaller accent side branch
      newBranch(nx, ny, b.angle + (Math.random() < 0.5 ? 1 : -1) * rnd(0.8, 1.5), b.depth + 1, b.neuron, b.id, idx, true);
    }
  }
  if (!any || branches.length >= MAX_BRANCHES && !branches.some(b => b.active)) growing = false;
}

// ================= SYNAPSE DETECTION =================
function detectSynapses() {
  const d2 = cfg.synDist * cfg.synDist;
  for (const a of branches) {
    if (!a.active || a.tipSyn) continue;
    const t = a.pts[a.pts.length - 1];
    for (const o of branches) {
      if (o.neuron === a.neuron || o.id === a.id) continue;
      const key = Math.min(a.id, o.id) + '-' + Math.max(a.id, o.id);
      if (synKeys.has(key)) continue;
      for (let i = o.pts.length - 1; i >= 0; i -= 2) {
        const p = o.pts[i], dx = p.x - t.x, dy = p.y - t.y;
        if (dx * dx + dy * dy < d2) {
          synKeys.add(key);
          synapses.push({ a: a.id, b: o.id, pa: a.pts.length - 1, pb: i, x: (p.x + t.x) / 2, y: (p.y + t.y) / 2, phase: rnd(0, 6.28), flash: 0 });
          a.tipSyn = true; a.active = false; // tip connected, stop growing
          break;
        }
      }
      if (a.tipSyn) break;
    }
  }
}

// ================= PULSE ANIMATION =================
function pathTo(b, idx) { // polyline from soma along ancestors to point idx of branch b
  let pts = b.pts.slice(0, idx + 1);
  while (b.parent >= 0) {
    const pi = b.parentIdx; b = branches[b.parent];
    pts = b.pts.slice(0, pi + 1).concat(pts);
  }
  return pts;
}
function spawnPulse() {
  if (!branches.length || pulses.length > 30) return;
  let pts, syn = null, mid = 0;
  if (synapses.length && Math.random() < 0.85) {
    syn = synapses[Math.floor(Math.random() * synapses.length)];
    const A = pathTo(branches[syn.a], syn.pa), B = pathTo(branches[syn.b], syn.pb).reverse();
    pts = A.concat(B); mid = A.length;
  } else {
    const b = branches[Math.floor(Math.random() * branches.length)];
    pts = pathTo(b, b.pts.length - 1);
  }
  if (pts.length < 2) return;
  const cum = [0];
  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y));
  pulses.push({ pts, cum, total: cum[cum.length - 1], d: 0, syn, midD: cum[Math.max(0, mid - 1)], hit: false });
}
function posAt(p, d) { // interpolate along polyline
  let i = 1;
  while (i < p.cum.length - 1 && p.cum[i] < d) i++;
  const seg = p.cum[i] - p.cum[i - 1] || 1, t = Math.min(1, Math.max(0, (d - p.cum[i - 1]) / seg));
  return { x: p.pts[i - 1].x + (p.pts[i].x - p.pts[i - 1].x) * t, y: p.pts[i - 1].y + (p.pts[i].y - p.pts[i - 1].y) * t };
}
function updatePulses(dt) {
  pulseTimer += dt * cfg.pulseFreq;
  while (pulseTimer >= 1) { pulseTimer--; spawnPulse(); }
  for (const p of pulses) {
    p.d += cfg.pulseSpeed * dt;
    if (p.syn && !p.hit && p.d >= p.midD) { p.hit = true; p.syn.flash = 1; }
  }
  pulses = pulses.filter(p => p.d < p.total + 30);
  for (const s of synapses) s.flash = Math.max(0, s.flash - dt * 1.5);
}

// ================= RENDERING =================
function drawSmooth(pts) { // quadratic smoothing through midpoints
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length - 1; i++) {
    const mx = (pts[i].x + pts[i + 1].x) / 2, my = (pts[i].y + pts[i + 1].y) / 2;
    ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my);
  }
  const l = pts[pts.length - 1];
  ctx.lineTo(l.x, l.y);
  ctx.stroke();
}
function renderBackground(time) {
  ctx.shadowBlur = 0;
  ctx.fillStyle = cfg.bgColor;
  ctx.fillRect(0, 0, W, H);
  const g = ctx.createRadialGradient(W / 2, H / 2, 40, W / 2, H / 2, 520);
  g.addColorStop(0, GLOW); g.addColorStop(1, 'rgba(16,26,58,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = GRID; ctx.lineWidth = 1; ctx.beginPath();
  for (let i = 0; i <= W; i += 50) { ctx.moveTo(i, 0); ctx.lineTo(i, H); ctx.moveTo(0, i); ctx.lineTo(W, i); }
  ctx.stroke();
  ctx.fillStyle = GRID; // scanlines, slowly scrolling
  const off = (time * 0.02) % 4;
  for (let y = off; y < H; y += 4) ctx.fillRect(0, y, W, 1);
  ctx.fillStyle = 'rgba(214,255,0,0.05)'; // gritty noise specks
  for (let i = 0; i < 60; i++) ctx.fillRect(Math.random() * W, Math.random() * H, 1.5, 1.5);
}
function render(time) {
  renderBackground(time);
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  // branches
  for (const b of branches) {
    if (b.pts.length < 2) continue;
    const c = b.accent ? cfg.accentColor : cfg.branchColor;
    ctx.strokeStyle = c; ctx.shadowColor = c; ctx.shadowBlur = 8; ctx.lineWidth = b.w;
    drawSmooth(b.pts);
  }
  // growing tips
  if (growing) for (const b of branches) if (b.active) {
    const t = b.pts[b.pts.length - 1];
    ctx.fillStyle = cfg.accentColor; ctx.shadowColor = cfg.accentColor; ctx.shadowBlur = 10;
    ctx.beginPath(); ctx.arc(t.x, t.y, 1.8, 0, 6.28); ctx.fill();
  }
  // somas
  for (const s of somas) {
    const r = 6 + Math.sin(time * 0.003 + s.phase) * 1.2;
    ctx.fillStyle = '#05070f'; ctx.strokeStyle = cfg.branchColor; ctx.shadowColor = cfg.branchColor; ctx.shadowBlur = 18; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(s.x, s.y, r, 0, 6.28); ctx.fill(); ctx.stroke();
  }
  // synapses: brighter than branches
  for (const s of synapses) {
    const k = 0.5 + 0.5 * Math.sin(time * 0.004 + s.phase), r = 2.5 + k * 1.5 + s.flash * 3;
    ctx.fillStyle = cfg.synColor; ctx.shadowColor = cfg.synColor;
    ctx.shadowBlur = cfg.synGlow * (0.7 + 0.5 * k + s.flash * 1.5);
    ctx.beginPath(); ctx.arc(s.x, s.y, r, 0, 6.28); ctx.fill();
    ctx.beginPath(); ctx.arc(s.x, s.y, r * 0.6, 0, 6.28); ctx.fill();
  }
  // pulses as sparks with a short trail
  for (const p of pulses) {
    if (p.d > p.total) continue;
    for (let i = 0; i < 6; i++) {
      const q = posAt(p, Math.max(0, p.d - i * 6)), f = 1 - i / 6;
      ctx.globalAlpha = f;
      ctx.fillStyle = cfg.pulseColor; ctx.shadowColor = cfg.pulseColor; ctx.shadowBlur = cfg.pulseBright * f;
      ctx.beginPath(); ctx.arc(q.x + (i ? rnd(-1, 1) : 0), q.y + (i ? rnd(-1, 1) : 0), 2.6 * f + 0.4, 0, 6.28); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
  // vignette
  ctx.shadowBlur = 0;
  const v = ctx.createRadialGradient(W / 2, H / 2, 300, W / 2, H / 2, 580);
  v.addColorStop(0, 'rgba(0,0,0,0)'); v.addColorStop(1, 'rgba(0,0,0,0.65)');
  ctx.fillStyle = v; ctx.fillRect(0, 0, W, H);
  // status text
  ctx.fillStyle = UI; ctx.font = '11px monospace';
  ctx.fillText((paused ? 'PAUSED' : growing ? 'GROWING' : 'ALIVE') + '  B:' + branches.length + ' S:' + synapses.length, 12, H - 12);
}

// ================= MAIN LOOP =================
function loop(now) {
  const dt = Math.min(0.05, (now - last) / 1000); last = now;
  if (!paused) {
    frame++;
    if (growing) {
      growAcc += cfg.growSpeed;
      while (growAcc >= 1) { growAcc--; growStep(); }
      if (frame % 4 === 0) detectSynapses();
    }
    updatePulses(dt);
  }
  render(now);
  requestAnimationFrame(loop);
}
setupGUI();
generate();
requestAnimationFrame(loop);
</script>
</body>
</html>
